import{c as e,Q as a,j as s,m as l}from"./chunks/framework.DOi4mjdC.js";const n="/assets/%E9%80%9A%E8%BF%87SetNextTaskStart%E5%AE%9E%E7%8E%B0%E5%B9%B6%E8%A1%8C%E7%A4%BA%E6%84%8F%E5%9B%BE.BCgEtfgz.png",_=JSON.parse('{"title":"SetNextTaskStart","description":"","frontmatter":{},"headers":[{"level":1,"title":"SetNextTaskStart","slug":"setnexttaskstart"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/同步控制/任务间同步/SetNextTaskStart.md","filePath":"api/SIMD-API/基础API/同步控制/任务间同步/SetNextTaskStart.md"}'),r={name:"api/SIMD-API/基础API/同步控制/任务间同步/SetNextTaskStart.md"};function d(i,t,p,o,c,h){return a(),s("div",null,[...t[0]||(t[0]=[l('<h1 id="setnexttaskstart" tabindex="-1">SetNextTaskStart <a class="header-anchor" href="#setnexttaskstart" aria-label="Permalink to &quot;SetNextTaskStart&quot;">​</a></h1><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>本接口为试验接口，在后续版本中可能会调整或改进，不保证后续兼容性。请开发者在使用过程中关注后续版本更新。</p></div><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th><th>备注</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td><td>该接口生效</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td><td>该接口生效</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td><td>仅保证编译兼容，实际功能不生效。</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td><td>仅保证编译兼容，实际功能不生效。</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td><td>仅保证编译兼容，实际功能不生效。</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>√</td><td>仅保证编译兼容，实际功能不生效。</td></tr><tr><td>Atlas 训练系列产品</td><td>√</td><td>仅保证编译兼容，实际功能不生效。</td></tr><tr><td>Kirin X90</td><td>√</td><td>仅保证编译兼容，实际功能不生效。</td></tr><tr><td>Kirin 9030</td><td>√</td><td>仅保证编译兼容，实际功能不生效。</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>在SuperKernel的子Kernel中调用，调用后的指令可以和后续其他的子Kernel实现并行，提升整体性能。如<a href="#fig37581010773">图1</a>所示，SuperKernel按序调用子Kernel，为保证子Kernel之间数据互不干扰，会在子Kernel间插入算子间同步进行保序，子KernelN-1调用该接口后，之后的指令会和后续子KernelN实现并行。</p><p>SuperKernel是一种算子的二进制融合技术，与源码融合不同，它聚焦于内核函数 (Kernel) 的二进制的调度方案，展开深度优化，于已编译的二进制代码基础上融合创建一个超级Kernel函数（SuperKernel），以调用子函数的方式调用多个其他内核函数，也就是子Kernel。相对于单算子下发，SuperKernel技术可以减少任务调度等待时间和调度开销，同时利用Task间隙资源进一步优化算子头开销。</p><p><strong>开发者需要自行保证调用此接口后的指令不会与后序算子互相干扰而导致精度问题，推荐在整个算子最后一条搬运指令后调用此接口。</strong></p><p><strong>图 1</strong> 通过SetNextTaskStart实现并行示意图<br><img src="'+n+`" alt="" title="通过SetNextTaskStart实现并行示意图"></p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>该原型在如下产品型号支持：</p><p>Ascend 950PR/Ascend 950DT</p><p>Atlas A3 训练系列产品/Atlas A3 推理系列产品</p><p>Atlas A2 训练系列产品/Atlas A2 推理系列产品</p><p>Atlas 200I/500 A2 推理产品</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template&lt;pipe_t AIV_PIPE = PIPE_MTE3, pipe_t AIC_PIPE = PIPE_FIX&gt;</span></span>
<span class="line"><span>__aicore__ inline void SetNextTaskStart()</span></span></code></pre></div></li><li><p>该原型在如下产品型号支持：</p><p>Atlas 推理系列产品AI Core</p><p>Atlas 训练系列产品</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template&lt;pipe_t AIV_PIPE = PIPE_MTE3, pipe_t AIC_PIPE = PIPE_MTE3&gt;</span></span>
<span class="line"><span>__aicore__ inline void SetNextTaskStart()</span></span></code></pre></div></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>AIV_PIPE</td><td>SetNextTaskStart之后运行的指令，如果位于AIV上的AIV_PIPE流水，可以与后序算子并行。AIV_PIPE的取值范围为PIPE_MTE2、PIPE_MTE3、PIPE_S、PIPE_V，流水类型介绍可参考硬件流水类型。</td></tr><tr><td>AIC_PIPE</td><td>SetNextTaskStart之后运行的指令，如果位于AIC上的AIC_PIPE流水，可以与后序算子并行。AIC_PIPE的取值范围为PIPE_MTE1、PIPE_MTE2、PIPE_MTE3、PIPE_FIX、PIPE_M，流水类型介绍可参考硬件流水类型。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>该接口适用于TorchAir图模式开发场景，且需在启用SuperKernel特性后方可生效。相关信息可参考《PyTorch图模式使用指南(TorchAir)》中的“GE图模式 &gt; GE图模式功能 &gt; 图内标定SuperKernel范围”章节。</li><li>在算子运行过程中，需要保证此接口在每个核上都被调用，且每个核上仅被调用一次。</li><li>若子Kernel某个TilingKey分支调用了此接口，则开发者需要保证当前算子可能会运行的所有TilingKey均调用了此接口，否则会出现因同步指令数量不匹配而卡住的现象。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>详细示例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/02_features/03_basic_api/06_sync_control/task_sync" target="_blank" rel="noreferrer">TaskSync样例</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;kernel_operator.h&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>AscendC::LocalTensor&lt;half&gt; dstLocal = outQueueDst.DeQue&lt;half&gt;();</span></span>
<span class="line"><span>AscendC::DataCopy(dstGlobal, dstLocal, 512);</span></span>
<span class="line"><span>// 在最后一条搬运指令后调用，使之后的指令可与后续子kernel并行执行</span></span>
<span class="line"><span>AscendC::SetNextTaskStart();</span></span>
<span class="line"><span>outQueueDst.FreeTensor(dstLocal);</span></span></code></pre></div>`,21)])])}const P=e(r,[["render",d]]);export{_ as __pageData,P as default};
